#[path="../mixer.rs"]mod mixer;
fn main(){use std::{path::Path,sync::{Arc,atomic::{AtomicBool,Ordering}},time::Instant};let input=Path::new("Clips/preparation30-fixture.mp4");let helper=Path::new("media-export.exe");let start=Instant::now();let path=mixer::preview(helper,input,mixer::AudioMix::default(),Arc::new(AtomicBool::new(false))).unwrap();println!("30SEC elapsed_ms={} bytes={} path={}",start.elapsed().as_millis(),std::fs::metadata(&path).unwrap().len(),path.display());std::fs::remove_file(&path).unwrap();assert!(!path.exists());let parent=path.parent().unwrap();let before=std::fs::read_dir(parent).unwrap().count();let flag=Arc::new(AtomicBool::new(true));assert!(mixer::preview(helper,input,mixer::AudioMix::default(),flag).is_err());assert_eq!(std::fs::read_dir(parent).unwrap().count(),before);let flag=Arc::new(AtomicBool::new(false));let copy=flag.clone();std::thread::spawn(move||{std::thread::sleep(std::time::Duration::from_millis(90));copy.store(true,Ordering::SeqCst);});assert!(mixer::preview(helper,input,mixer::AudioMix::default(),flag).is_err());assert_eq!(std::fs::read_dir(parent).unwrap().count(),before);println!("PASS initial and in-progress cancellation remove partial audition; successful deletion confirmed");}
